class CastingExample{getInfo(){return{id:"castexample",name:"Casting Example",blocks:[{opcode:"toNumber",blockType:Scratch.BlockType.REPORTER,text:"convert [INPUT] to number",arguments:{INPUT:{type:Scratch.ArgumentType.STRING,defaultValue:"3.0"}}},{opcode:"castToString",blockType:Scratch.BlockType.REPORTER,text:"convert [INPUT] to string",arguments:{INPUT:{type:Scratch.ArgumentType.STRING,defaultValue:"Hello"}}},{opcode:"toBoolean",blockType:Scratch.BlockType.BOOLEAN,text:"convert [INPUT] to boolean",arguments:{INPUT:{type:Scratch.ArgumentType.STRING,defaultValue:"1"}}},{opcode:"compare",blockType:Scratch.BlockType.REPORTER,text:"compare [A] to [B]",arguments:{A:{type:Scratch.ArgumentType.STRING,defaultValue:"3"},B:{type:Scratch.ArgumentType.STRING,defaultValue:"5"}}}]}}toNumber({INPUT:e}){return Scratch.Cast.toNumber(e)}castToString({INPUT:e}){return Scratch.Cast.toString(e)}toBoolean({INPUT:e}){return Scratch.Cast.toBoolean(e)}compare({A:e,B:t}){const a=Scratch.Cast.compare(e,t);return 0===a?"Equal":a>0?"A is greater":a<0?"B is greater":void 0}}Scratch.extensions.register(new CastingExample);